    [Theory]
    [MemberData(nameof(SourceValues))]
    public async Task ThaiPages_PreserveSourceCopyInBothRouteModes(string route, string flag, string[] values)
    {
        foreach (var active in new[] { true, false })
        {
            await using var host = factory.WithWebHostBuilder(builder => builder.UseSetting("BlazorRouting:" + flag, active ? "true" : "false"));
            using var client = host.CreateClient(new WebApplicationFactoryClientOptions { AllowAutoRedirect = false });
            using var response = await client.GetAsync(route + "?culture=th");
            if (route == "/services/3d-design" && !active)
            {
                // The application has no Razor fallback page for this route.
                Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
                continue;
            }
            Assert.Equal(HttpStatusCode.OK, response.StatusCode);
            var html = WebUtility.HtmlDecode(await response.Content.ReadAsStringAsync());
            // Structured FAQ JSON may encode Thai characters as Unicode escapes.
            html = Regex.Replace(html, @"\\u([0-9a-fA-F]{4})", match => ((char)Convert.ToInt32(match.Groups[1].Value, 16)).ToString());
            foreach (var value in values) { Assert.Contains(value, html, StringComparison.Ordinal); }
        }
    }
